# May 2025
# This R script rationalizes and rounds the figures/estimates created in the upstream R scripts so that they conform with the guidelines for the DfE 'Exploring
# Education Statistics' production platform system, where GLMS is published. This script covers workers in part-time employment for GLMS. 
# The Outputs generated by the script includes a data file and meta-file in CSV format for uploading on to the EES platform.


######################
# Part-time EES code #
######################


### Read in files

PT_employment_rates_original <-readRDS(paste0(filepath, data_folder,start_year,"_",end_year,".rds"))

PT_breakdowns_emp_rates_original <-readRDS(paste0(filepath, data_folder,start_year,"_",end_year,".rds"))


# NOTE THAT WHAT IS GENERATED HERE ARE THE PROPORTION OF WORKERS/EMPLOYEES THAT WORK PART TIME - THESE DO NOT
# GENERATE PART TIME EMPLOYMENT RATES

### PT employment rates

# Creates new columns for EES standards - time and geography
# Renames columns
PT_employment_rates <- PT_employment_rates_original %>%
  mutate(time_identifier = "Calendar year",
         geographic_level = "National",
         country_code = "E92000001",
         country_name = "England") %>%
  rename(time_period = Year,
         age_group = Age_range,
         graduate_type = Population)

# Makes all column names lower case
colnames(PT_employment_rates) <- tolower(colnames(PT_employment_rates))

# Select the variables needed and reorder
PT_employment_rates <- PT_employment_rates %>%
  select("time_period",
         "time_identifier",
         "geographic_level",
         "country_code",
         "country_name",
         "age_group",
         "graduate_type",
        "pt_employment_rate",
#        "pt_employment_proportion", # Renamed variable
         "pt_employment_accuracy_flag",
         "pt_employment_suppression_flag")


# Ungroups data (that was previously grouped using group_by function)
# Filters out all cases where graduate type is not in scope
PT_employment_rates <- PT_employment_rates %>%
  ungroup() %>%
  filter(!graduate_type == "Not in scope")

# Multiplies rates by 100 and rounds to one decimal place
PT_employment_rates <- PT_employment_rates %>%
  mutate(pt_employment_rate = pt_employment_rate*100) %>%
  mutate(pt_employment_rate = formatC(pt_employment_rate, digits = 1, format = "f")) 

PT_employment_rates <- PT_employment_rates %>%
mutate(pt_employment_proportion = pt_employment_rate)

# Tweak the name of the accuracy flag here - March 2025 change
PT_employment_rates <- PT_employment_rates %>%
mutate(employment_accuracy = pt_employment_accuracy_flag) %>% # removing pt from the variable name on advice from EES Team March 2025
mutate(employment_suppression = pt_employment_suppression_flag) %>%  
mutate(age_band = age_group) %>%  
mutate(employment_proportion_part_time = pt_employment_proportion) %>%  # amended to recommendation of EES Team March 2025
    # Select the variables needed and reorder
# PT_employment_rates <- PT_employment_rates %>%
  select("time_period",
         "time_identifier",
         "geographic_level",
         "country_code",
         "country_name",
         "age_band",
         "graduate_type",
#        "pt_employment_rate",
#         "pt_employment_proportion", # Renamed variable
          "employment_proportion_part_time", # see above - changed to recommendation of the EES Team in March 2025
         "employment_accuracy", # same as above
         "employment_suppression")


# Revalue some of the values in the graduate_type
PT_employment_rates <- PT_employment_rates %>%
  mutate(graduate_type = recode(graduate_type, 
                                "Non grad" = "Non-graduate",
                                "Post grad" = "Postgraduate"))

# remove the suppression flag after checking that no rows need to be suppressed below
# PT_employment_rates <- PT_employment_rates %>%
#  select(-(pt_employment_suppression))



readr::write_csv(PT_employment_rates,
                 paste0(filepath, data_folder,label_EES,".csv"))


# Make a table for the meta data
PT_employment_rates.meta <- data.frame("col_name" = c("employment_proportion_part_time",
                                                      "age_band",
                                                      "graduate_type"),
                                       "col_type" = c("Indicator",
                                                      "Filter",
                                                      "Filter"),
                                       "label" = c("Proportion of part-time workers",
                                                   "Age band",
                                                   "Graduate type"),
                                       "indicator_grouping" = c("","",""),
                                       "indicator_unit" = c("%","",""),
                                       "indicator_dp"= c("1","",""),
                                       "filter_hint" = c("","Select the Age group you are interested in","Select the Graduate type you are interested in"),
                                       "filter_grouping_column"=c("","",""))

readr::write_csv(PT_employment_rates.meta,
                 paste0(filepath, data_folder,label_EES,".meta.csv"))





### PT Breakdowns

# Creates new columns for EES standards - time and geography
# Renames columns
PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates_original %>%
  mutate(time_identifier = "Calendar year",
         geographic_level = "National",
         country_code = "E92000001",
         country_name = "England") %>%
  rename(time_period = Year,
         pt_breakdown = Breakdown,
         pt_characteristic = Population)

# Makes all column names lower case
colnames(PT_breakdowns_emp_rates) <- tolower(colnames(PT_breakdowns_emp_rates))

# Ungroups data (that was previously grouped using group_by function)
# Filters out all cases wheregraduate type is not in scope
PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
  ungroup() %>%
  filter(!graduate_type == "Not in scope")

PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
  mutate(pt_employment_proportion = pt_employment_rate) 
# Tweak the name of the accuracy flag slightly - applied March 2025

PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
mutate(employment_accuracy = pt_employment_accuracy_flag)  %>% # Amending names of accuracy, suppression and empty flags on advice from the EES Team March 2025
mutate(employment_suppression = pt_employment_suppression_flag)  %>% 
mutate(employment_proportion_part_time = pt_employment_proportion)  %>%
mutate(breakdown = pt_breakdown)  %>%
mutate(employment_empty = pt_employment_empty_flag)  %>% 
mutate(breakdown_topic = pt_characteristic)  %>%   
  # Select the variables needed and reorder
# PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
  select("time_period",
         "time_identifier",
         "geographic_level",
         "country_code",
         "country_name",
         "graduate_type",
#         "pt_characteristic",
          "breakdown_topic", # changes suggested by the EES Team in March 2025
           "breakdown", # changes suggested by the EES Team in March 2025
#         "pt_breakdown",
#         "pt_employment_rate",
#          "pt_employment_proportion",
         "employment_proportion_part_time",  # amended to suggestion from EES Team in March 2025
         "employment_accuracy",
         "employment_suppression",
         "employment_empty")


# Multiplies rates by 100 and rounds to one decimal place
PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
  mutate(employment_proportion_part_time = employment_proportion_part_time*100) %>%
  mutate(employment_proportion_part_time = formatC(employment_proportion_part_time, digits = 1, format = "f"))

# Revalue some of the values in the graduate_type
PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
  mutate(graduate_type = recode(graduate_type, 
                                "Non grad" = "Non-graduate",
                                "Post grad" = "Postgraduate")) %>% 
  
  
  mutate(breakdown = recode(breakdown, # pt_breakdown changed to just breakdown on advice from the EES team March 2025
                               "16-20" = "16-20",
                               "21-30" = "21-30",
                               "31-40" = "31-40",
                               "41-50" = "41-50",
                               "51-60" = "51-60",
                               "61-64" = "61-64")) %>% 
  
  
  
  mutate(breakdown_topic = recode(breakdown_topic,
                                    "AGE_BANDS" = "Age band",
                                    "SEX" = "Sex")) # March 2025 Needs to be set to Sex as this is the relevant filed taken from the LFS data

# apply suppression process below: This was the only section where suppression 
# needed to be applied
PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
  mutate(employment_proportion_part_time = ifelse(employment_suppression == 1, "c", employment_proportion_part_time))

PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
  mutate(employment_proportion_part_time = ifelse(employment_empty == 1, "z", employment_proportion_part_time)) ####Steve might need to change letter

# remove the suppression flags as have no value to the output file
# PT_breakdowns_emp_rates <- PT_breakdowns_emp_rates %>%
#  select(-c(pt_employment_suppression_flag, pt_employment_empty_flag))


readr::write_csv(PT_breakdowns_emp_rates,
                 paste0(filepath, data_folder,label_EES,".csv"))


# Make a table for the meta data
PT_breakdowns_emp_rates.meta <- data.frame("col_name" = c("employment_proportion_part_time",
                                                          "graduate_type",
                                                      #    "breakdown_topic",
                                                          "breakdown"),
                                           "col_type" = c("Indicator",
                                                          "Filter",
                                                        #  "Filter",
                                                          "Filter"),
                                           "label" = c("Proportion of part-time workers",
                                                       "Graduate type",
                                                      # "Characteristic",
                                                       "Charcteristic breakdowns"),
                                           "indicator_grouping" = c("","",""),   # ""),
                                           "indicator_unit" = c("%", "",""),    #  ""),
                                           "indicator_dp"= c("1","",""), # ""),
                                           "filter_hint" = c("","Select the Graduate type you are interested in", "Select the characteristic breakdown you are interested in"), # , "Select the breakdown you are interested in"),
                                           "filter_grouping_column"=c("", "",""))  ###,""))

readr::write_csv(PT_breakdowns_emp_rates.meta,
                 paste0(filepath, data_folder,label_EES,".meta.csv"))


